<?php declare(strict_types=1);require __DIR__.'/bootstrap.php';header('Cache-Control: no-store, no-cache, must-revalidate, max-age=0');header('Pragma: no-cache');$login=valid_login((string)($_GET['login']??''));?>
<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tráfego Huawei</title>
<style>:root{font-family:Arial;color:#183246;background:#eaf1f5}*{box-sizing:border-box}body{margin:0;padding:28px}.top{max-width:1420px;margin:0 auto 18px;display:flex;justify-content:flex-end}.back{background:#17374a;color:#fff;padding:11px 17px;border-radius:9px;text-decoration:none;font-weight:bold}.layout{max-width:1420px;margin:auto;display:grid;grid-template-columns:390px 1fr;gap:28px}.card{background:#fff;border-radius:16px;padding:26px;box-shadow:0 8px 26px #17344c15}.profile{background:#193649;color:#fff}.profile h1.blocked-name{color:#ff7d89}.kv{display:grid;grid-template-columns:125px 1fr;border-bottom:1px solid #ffffff20;padding:10px 0;gap:8px}.cut-tag{display:inline-block;margin-left:5px;padding:3px 6px;border-radius:5px;font-size:10px;font-style:normal;font-weight:800;vertical-align:middle}.cut-ok{background:#dff6e7;color:#126b35}.cut-warn{background:#fff0c7;color:#7e5900}.cut-normal{background:#e8eef4;color:#44586a}.cut-error{background:#ffdce0;color:#a71927}.blocked-state{color:#ff8b95;font-weight:800}.actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:20px}.btn{padding:11px 15px;border-radius:8px;text-decoration:none;background:#1371c8;color:#fff;font-weight:bold}.head{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #dfe7ec;margin-bottom:18px}.live{background:#e7f7ed;color:#176c38;padding:8px 12px;border-radius:18px;font-weight:bold}.chart{width:100%;height:320px;background:#f5f8fa;border:1px solid #dbe5eb;border-radius:12px}.legend{font-size:18px;margin-top:14px;display:flex;gap:28px}.muted{color:#657482}.note{background:#fff4d6;color:#765600;padding:12px;border-radius:8px}@media(max-width:900px){.layout{grid-template-columns:1fr}body{padding:16px}}</style></head><body>
<div class="top"><a class="back" href="./">← SAIR DO MONITORAMENTO</a></div><div class="layout"><aside class="card profile"><small>MONITORAMENTO DO CLIENTE</small><h1 id="clientName"><?=htmlspecialchars($login)?></h1><div id="fields"></div><div class="actions"><a class="btn" href="/admin/addons/busca_inteligente/det_conn.php?login=<?=urlencode($login)?>">LOG DE CONEXÕES</a></div></aside>
<main class="card"><div class="head"><h2>Tráfego em tempo real</h2><div style="display:flex;align-items:center;gap:14px"><label style="display:flex;align-items:center;gap:6px;font-size:14px;cursor:pointer;user-select:none"><input id="showPointLabels" type="checkbox"> Exibir valores nos pontos</label><span class="live">● SNMP Huawei</span></div></div><canvas id="chart" class="chart" width="1000" height="320"></canvas><div class="legend"><span>↓ Download <b id="down">0.00</b> Mbps</span><span>↑ Upload <b id="up">0.00</b> Mbps</span></div><p id="status" class="muted">Localizando o assinante na HUAWEI-AAA-MIB…</p><p class="note">O gráfico consulta diretamente, via SNMP, os contadores individuais de 64 bits do assinante no Huawei. Não usa RADIUS nem abre SSH.</p></main></div>
<script>
const login=<?=json_encode($login)?>,ctx=document.getElementById('chart').getContext('2d'),clientName=document.getElementById('clientName'),fields=document.getElementById('fields'),down=document.getElementById('down'),up=document.getElementById('up'),statusEl=document.getElementById('status'),pointLabels=document.getElementById('showPointLabels');let prev=null,points=[],started=null;pointLabels.addEventListener('change',()=>draw());const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),uptime=()=>{if(!started||isNaN(started))return'-';let n=Math.max(0,Math.floor((Date.now()-started.getTime())/1000)),d=Math.floor(n/86400);n%=86400;return(d?d+'d ':'')+String(Math.floor(n/3600)).padStart(2,'0')+'h '+String(Math.floor(n%3600/60)).padStart(2,'0')+'m'};
fetch('api_client.php?login='+encodeURIComponent(login)).then(r=>r.json()).then(j=>{if(!j.ok)throw Error(j.error);let c=j.client,q=j.qos||{},cut=c.cut_status||{},blocked=!!cut.system_blocked,rate=n=>n?`${(Number(n)/1e6).toFixed(2)} Mbps`:'-',badge=(actual,missing=false)=>{if(blocked)return actual?'<em class="cut-tag cut-ok">CORTE OK</em>':'<em class="cut-tag cut-warn">CORTE PENDENTE</em>';if(actual)return'<em class="cut-tag cut-error">CORTE INDEVIDO</em>';return missing?'<em class="cut-tag cut-normal">SEM IPv6</em>':'<em class="cut-tag cut-normal">NORMAL</em>'};started=new Date(String(c.acctstarttime||'').replace(' ','T'));clientName.textContent=c.nome||c.username;clientName.classList.toggle('blocked-name',blocked);let data=[['Login',esc(c.username)],['Status','Online'],['Bloqueio MK-AUTH',blocked?'<strong class="blocked-state">BLOQUEADO</strong>':'Não bloqueado'],['Contrato',esc(c.contrato||'-')],['Conectado às',esc(c.acctstarttime)],['Uptime',esc(uptime())],['IPv4',esc(c.framedipaddress||'-')+' '+badge(!!cut.ipv4_cut)],['IPv6',esc(c.ipv6_address||'-')+' '+badge(!!cut.ipv6_wan_cut,!c.ipv6_address)],['IPv6-PD',esc(c.ipv6_pd_prefix||'-')+' '+badge(!!cut.ipv6_pd_cut,!c.ipv6_pd_prefix)],['MAC',esc(c.callingstationid)],['Porta/VLAN',esc(c.nasportid)],['Plano',esc(c.plano||'-')],['Ramal',esc(c.ramal||'-')]];fields.innerHTML=data.map(x=>`<div class="kv"><b>${esc(x[0])}</b><span data-key="${esc(x[0])}">${x[1]}</span></div>`).join('');let box=document.getElementById('qosSummary');if(box){box.className='qos '+(q.ok?'qos-ok':'qos-bad');box.innerHTML=`<b>QoS ${q.ok?'correto':'divergente'}</b><span>↓ Download ${rate(q.output_bps)}</span><span>↑ Upload ${rate(q.input_bps)}</span><small>Validação dos atributos Huawei enviados pelo RADIUS para o plano ${esc(c.plano||'-')}.</small>`}setInterval(()=>{let u=fields.querySelector('[data-key="Uptime"]');if(u)u.textContent=uptime()},1000)}).catch(e=>statusEl.textContent=e.message);
function draw(hoverIndex=null){ctx.clearRect(0,0,1000,320);const left=70,right=20,top=16,bottom=36,base=320-bottom,plotW=1000-left-right,plotH=base-top;let peak=Math.max(.01,...points.flatMap(p=>[p.d,p.u])),power=Math.pow(10,Math.floor(Math.log10(peak))),normalized=peak/power,step=(normalized<=1?0.25:normalized<=2?0.5:normalized<=5?1:2)*power,max=Math.max(step,Math.ceil(peak/step)*step),den=Math.max(1,points.length-1),px=i=>left+i*plotW/den,py=v=>base-v/max*plotH,fmt=v=>v>=100?Math.round(v):v>=10?v.toFixed(1):v.toFixed(2);ctx.save();ctx.font='12px Arial';ctx.textAlign='right';ctx.textBaseline='middle';for(let i=0;i<=4;i++){let value=max*i/4,y=base-plotH*i/4;ctx.strokeStyle=i===0?'#9eabb8':'#dce4ec';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(left,y);ctx.lineTo(1000-right,y);ctx.stroke();ctx.fillStyle='#607080';ctx.fillText(fmt(value),left-9,y)}ctx.save();ctx.translate(15,top+plotH/2);ctx.rotate(-Math.PI/2);ctx.textAlign='center';ctx.fillStyle='#607080';ctx.fillText('Mbps',0,0);ctx.restore();if(points.length){let labels=Math.min(5,points.length);ctx.textAlign='center';ctx.textBaseline='top';for(let n=0;n<labels;n++){let i=labels===1?0:Math.round(n*(points.length-1)/(labels-1));ctx.fillStyle='#607080';ctx.fillText(points[i].time,px(i),base+9)}}ctx.restore();for(const[k,color,fill]of[['d','#e75252','rgba(231,82,82,.20)'],['u','#2679c9','rgba(38,121,201,.20)']]){if(points.length){ctx.beginPath();ctx.moveTo(px(0),base);points.forEach((p,i)=>ctx.lineTo(px(i),py(p[k])));ctx.lineTo(px(points.length-1),base);ctx.closePath();ctx.fillStyle=fill;ctx.fill()}ctx.strokeStyle=color;ctx.lineWidth=4;ctx.beginPath();points.forEach((p,i)=>{let x=px(i),y=py(p[k]);i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke()}if(pointLabels.checked){ctx.save();ctx.font='bold 12px Arial';ctx.textAlign='center';ctx.textBaseline='bottom';points.forEach((p,i)=>{let x=px(i),yd=py(p.d),yu=py(p.u);ctx.fillStyle='#fff';ctx.strokeStyle='#e75252';ctx.lineWidth=2;ctx.beginPath();ctx.arc(x,yd,3,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle='#b52f2f';ctx.fillText('Tx: '+p.d.toFixed(1),x,Math.max(top+13,yd-7));ctx.fillStyle='#fff';ctx.strokeStyle='#2679c9';ctx.beginPath();ctx.arc(x,yu,3,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle='#1764a6';ctx.textBaseline='top';ctx.fillText('Rx: '+p.u.toFixed(1),x,Math.min(base-13,yu+7));ctx.textBaseline='bottom'});ctx.restore()}if(hoverIndex===null||!points[hoverIndex])return;let p=points[hoverIndex],x=px(hoverIndex),yd=py(p.d),yu=py(p.u);ctx.save();ctx.strokeStyle='#66788a';ctx.lineWidth=1;ctx.setLineDash([5,4]);ctx.beginPath();ctx.moveTo(x,top);ctx.lineTo(x,base);ctx.stroke();ctx.setLineDash([]);for(const[y,color]of[[yd,'#e75252'],[yu,'#2679c9']]){ctx.fillStyle='#fff';ctx.strokeStyle=color;ctx.lineWidth=4;ctx.beginPath();ctx.arc(x,y,6,0,Math.PI*2);ctx.fill();ctx.stroke()}let lines=[p.time,'Tx  '+p.d.toFixed(2)+' Mbps','Rx  '+p.u.toFixed(2)+' Mbps'],w=210,h=78,bx=Math.min(780,Math.max(left,x+14)),by=Math.max(8,Math.min(230,Math.min(yd,yu)-88));ctx.fillStyle='rgba(18,39,55,.94)';ctx.beginPath();ctx.roundRect?ctx.roundRect(bx,by,w,h,8):ctx.rect(bx,by,w,h);ctx.fill();ctx.fillStyle='#fff';ctx.font='bold 14px Arial';ctx.fillText(lines[0],bx+12,by+21);ctx.font='14px Arial';ctx.fillStyle='#ff8585';ctx.fillText(lines[1],bx+12,by+44);ctx.fillStyle='#75baff';ctx.fillText(lines[2],bx+12,by+65);ctx.restore()}
const POLL_MS=3000,STALE_AFTER_MS=75000,COUNTER_WARNING_MS=15000;let timer=null,lastRate={d:0,u:0},lastCounterChange=Date.now(),stopped=false;
function addPoint(d,u,sampleMs){lastRate={d,u};down.textContent=d.toFixed(2);up.textContent=u.toFixed(2);points.push({d,u,time:new Date(sampleMs).toLocaleTimeString()});if(points.length>30)points.shift();draw()}
async function sample(){if(stopped)return;try{let r=await fetch('api_realtime.php?login='+encodeURIComponent(login)+'&_='+Date.now(),{cache:'no-store'}),j=await r.json();if(!r.ok||!j.ok)throw Error(j.error||'Falha na consulta ao Huawei.');let warning=false;if(!prev){prev=j;lastCounterChange=Date.now();addPoint(0,0,j.sample_ms)}else{let downDelta=Number(j.down_bytes)-Number(prev.down_bytes),upDelta=Number(j.up_bytes)-Number(prev.up_bytes),changed=downDelta!==0||upDelta!==0,countersValid=downDelta>=0&&upDelta>=0;if(changed&&countersValid){let seconds=Math.max(.001,(Number(j.sample_ms)-Number(prev.sample_ms))/1000),d=downDelta*8/seconds/1e6,u=upDelta*8/seconds/1e6;addPoint(d,u,j.sample_ms);prev=j;lastCounterChange=Date.now()}else if(changed&&!countersValid){prev=j;lastRate={d:0,u:0};lastCounterChange=Date.now();addPoint(0,0,j.sample_ms);statusEl.textContent='Contadores SNMP reiniciados; recalculando a velocidade…'}else{let elapsed=Date.now()-lastCounterChange,stale=elapsed>=STALE_AFTER_MS;warning=elapsed>=COUNTER_WARNING_MS;addPoint(stale?0:lastRate.d,stale?0:lastRate.u,j.sample_ms);if(stale){prev=j;lastCounterChange=Date.now()}}}statusEl.textContent=warning?'Huawei não incrementou o contador deste assinante nos últimos 15 segundos.':(j.interface||'Huawei')+' · média SNMP contínua · atualizado '+new Date().toLocaleTimeString()}catch(e){statusEl.textContent='Monitoramento: '+e.message}finally{if(!stopped)timer=setTimeout(sample,POLL_MS)}}
document.getElementById('chart').addEventListener('mousemove',e=>{if(!points.length)return;let rect=e.currentTarget.getBoundingClientRect(),x=(e.clientX-rect.left)*1000/rect.width,index=points.length===1?0:Math.round((x-70)/910*(points.length-1));draw(Math.max(0,Math.min(points.length-1,index)))});document.getElementById('chart').addEventListener('mouseleave',()=>draw());
sample();addEventListener('beforeunload',()=>{stopped=true;if(timer)clearTimeout(timer)});
</script>
<script>
(function(){
 fetch('api_client.php?login='+encodeURIComponent(login)+'&validate='+Date.now(),{cache:'no-store'})
  .then(async r=>{let j=await r.json();if(!r.ok||!j.ok)throw Error(j.error||'Cliente não está online no Huawei.')})
  .catch(e=>{stopped=true;if(timer)clearTimeout(timer);document.querySelector('.layout').innerHTML='<main class="card" style="grid-column:1/-1;text-align:center"><h2>Cliente não conectado no Huawei</h2><p class="muted">'+esc(e.message)+'</p><p>Esta página mostra somente sessões cujo NAS-IP-Address corresponde ao Huawei configurado.</p><a class="btn" href="./">VOLTAR À LISTA</a></main>'});
})();
</script><style>.qos{display:flex;align-items:center;gap:18px;flex-wrap:wrap;margin:16px 0;padding:13px 15px;border-radius:10px}.qos-ok{background:#e7f7ed;color:#176c38}.qos-bad{background:#fdebec;color:#a9222d}.qos small{flex-basis:100%}</style><script>const qos=document.createElement('div');qos.id='qosSummary';qos.className='qos';qos.textContent='Validando QoS do plano…';document.querySelector('.legend').after(qos);</script></body></html>

